-- Messrunde 10c-4a -- Sitzung 4: M151, die Gleichheitsprobe zerlegt gegen ungeteilt
-- Auftrag:  "Prozessansicht -- freies Zeitfenster, Messrunde (Schritt 10c-4a)",
--           Stand 07.09.2026
-- Ergebnis: docs/process-view.md Paragraf 30 ff.
--
-- ERZEUGT von scripts/messung-prozessansicht-frei/erzeuge.py. Der Statementtext
-- kommt aus scripts/messung-prozessansicht/gerendert.txt (M116, aus
-- ProzessbaumRepository gefallen) und ist NUR in Ebene und Bereichspraedikat
-- variiert.
--
-- Ausschliesslich SELECT / SET / EXPLAIN. (Regel S1) Benutzer monitor_read.
-- G1: keine Zugangsdaten, kein Hostname. Mandanten-IDs sind Codes.
-- L9: SET max_statement_time = 60. Jedes Statement, das die Grenze reisst, ist
--     eine Abweichung vom Rahmen und wird als solche ausgewiesen.
--
-- Z1: Alle Fenster enden auf 2025-12-30 03:00:00 -- unterhalb des Dev-Ankers
--     2025-12-30 04:09:47, auf einer Stundengrenze, im dichten Bestand.
--
-- ZWECK. Ueber dasselbe Boesfall-Fenster: die ZERLEGTE Summe gegen die
-- UNGETEILTE Lesung der Stundenebene, verglichen je (process_id,
-- message_status) und ueber die Summe -- nicht nur als Gesamtsumme.
-- Zweimal je Mandant: Z-U (ein Statement) und die Z-D-Summe, in SQL
-- nachgebildet (die Arithmetik, die Java taete -- nicht Java selbst).
-- Erwartet: NULL abweichende Zeilen (Erwartung 5). Findet die Probe auch
-- nur eine, ist Ausgang 1 des Tors erreicht: sofort anhalten.
-- Kein Ergebnis dieser Sitzung traegt eine Prozesskennung (G1): Es werden
-- ausschliesslich Zaehler und Summen ausgegeben.

SELECT '=== 00 read_only (erste Abfrage der Sitzung) ===' AS marke;
SELECT @@global.read_only AS read_only, NOW() AS serverzeit, VERSION() AS version,
       @@max_statement_time AS grenze_vorher;

SET max_statement_time = 60;
SET profiling = 1;
SET profiling_history_size = 100;

SELECT '=== M151-NEXANS · Seitenzaehler: Zeilen und Nachrichten je Fassung ===' AS marke;
SELECT 'E ungeteilt (Stunde)' AS fassung, COUNT(*) AS zeilen, SUM(summe) AS nachrichten FROM (select `overlord_monitor`.`message_rollup`.`process_id`, `overlord_monitor`.`message_rollup`.`message_status`, sum(`overlord_monitor`.`message_rollup`.`anzahl`) as `summe` from `overlord_monitor`.`message_rollup` where (`overlord_monitor`.`message_rollup`.`stunde` >= timestamp '2024-12-29 14:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` < timestamp '2025-12-30 03:00:00.0' and exists (select 1 as `one` from `GlassfishDB`.`Process` as `baum_process` join `GlassfishDB`.`ProjectMandant` on `GlassfishDB`.`ProjectMandant`.`ProjectID` = `baum_process`.`ProjectID` where (`baum_process`.`ProcessID` = `overlord_monitor`.`message_rollup`.`process_id` and `GlassfishDB`.`ProjectMandant`.`MandantID` = 'NEXANS'))) group by `overlord_monitor`.`message_rollup`.`process_id`, `overlord_monitor`.`message_rollup`.`message_status`) AS e
