UNION ALL SELECT 'Z-D Summe (SQL)', COUNT(*), SUM(summe) FROM (select `u`.`process_id`, `u`.`message_status`, sum(`u`.`summe`) as `summe` from (select `overlord_monitor`.`message_rollup`.`process_id`, `overlord_monitor`.`message_rollup`.`message_status`, sum(`overlord_monitor`.`message_rollup`.`anzahl`) as `summe` from `overlord_monitor`.`message_rollup` where (((`overlord_monitor`.`message_rollup`.`stunde` >= timestamp '2024-12-29 14:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` < timestamp '2024-12-30 00:00:00.0') or (`overlord_monitor`.`message_rollup`.`stunde` >= timestamp '2025-12-30 00:00:00.0' and `overlord_monitor`.`message_rollup`.`stunde` < timestamp '2025-12-30 03:00:00.0')) and exists (select 1 as `one` from `GlassfishDB`.`Process` as `baum_process` join `GlassfishDB`.`ProjectMandant` on `GlassfishDB`.`ProjectMandant`.`ProjectID` = `baum_process`.`ProjectID` where (`baum_process`.`ProcessID` = `overlord_monitor`.`message_rollup`.`process_id` and `GlassfishDB`.`ProjectMandant`.`MandantID` = 'NEXANS'))) group by `overlord_monitor`.`message_rollup`.`process_id`, `overlord_monitor`.`message_rollup`.`message_status` union all select `overlord_monitor`.`message_rollup_tag`.`process_id`, `overlord_monitor`.`message_rollup_tag`.`message_status`, sum(`overlord_monitor`.`message_rollup_tag`.`anzahl`) as `summe` from `overlord_monitor`.`message_rollup_tag` where (((`overlord_monitor`.`message_rollup_tag`.`tag` >= date '2024-12-30' and `overlord_monitor`.`message_rollup_tag`.`tag` < date '2025-01-01') or (`overlord_monitor`.`message_rollup_tag`.`tag` >= date '2025-12-01' and `overlord_monitor`.`message_rollup_tag`.`tag` < date '2025-12-30')) and exists (select 1 as `one` from `GlassfishDB`.`Process` as `baum_process` join `GlassfishDB`.`ProjectMandant` on `GlassfishDB`.`ProjectMandant`.`ProjectID` = `baum_process`.`ProjectID` where (`baum_process`.`ProcessID` = `overlord_monitor`.`message_rollup_tag`.`process_id` and `GlassfishDB`.`ProjectMandant`.`MandantID` = 'NEXANS'))) group by `overlord_monitor`.`message_rollup_tag`.`process_id`, `overlord_monitor`.`message_rollup_tag`.`message_status` union all select `overlord_monitor`.`message_rollup_monat`.`process_id`, `overlord_monitor`.`message_rollup_monat`.`message_status`, sum(`overlord_monitor`.`message_rollup_monat`.`anzahl`) as `summe` from `overlord_monitor`.`message_rollup_monat` where (`overlord_monitor`.`message_rollup_monat`.`monat` >= date '2025-01-01' and `overlord_monitor`.`message_rollup_monat`.`monat` < date '2025-12-01' and exists (select 1 as `one` from `GlassfishDB`.`Process` as `baum_process` join `GlassfishDB`.`ProjectMandant` on `GlassfishDB`.`ProjectMandant`.`ProjectID` = `baum_process`.`ProjectID` where (`baum_process`.`ProcessID` = `overlord_monitor`.`message_rollup_monat`.`process_id` and `GlassfishDB`.`ProjectMandant`.`MandantID` = 'NEXANS'))) group by `overlord_monitor`.`message_rollup_monat`.`process_id`, `overlord_monitor`.`message_rollup_monat`.`message_status`) as `u` group by `u`.`process_id`, `u`.`message_status`) AS d;
